PROCEDURE calculateDiscount(price, discountRate)
{
   discountAmount ← price * discountRate
   finalPrice ← price + discountAmount
   RETURN finalPrice
}

PROCEDURE calculateGrade(score, totalPoints)
{
   percentage ← (score / totalPoints) * 100
   IF(percentage >= 90)
   {
      DISPLAY "A"
   }
   ELSE
   {
      IF(percentage >= 80)
      {
         DISPLAY "B"
      }
      ELSE
      {
         DISPLAY "C or below"
      }
   }
}
